        summary:Set(capacity..string.format("%d jenis item (%d total)  ·  %d gear  ·  %d dipakai\n%d hasil  ·  Halaman %d/%d",snapshot.itemKinds,snapshot.itemTotal,snapshot.gearTotal,snapshot.equippedTotal,#rows,page,pages))
