_yyshygnqr[41]={id=41,np=6,va=false,nuv=1,ms=15,sp={42,43,44,45,46,47},k={"api","live","connectData","loadstring","saveSetting","tabs","data","references","-- Optional development adapter. Read-only player data plus explicitly enabled cauldron crafting.\010return function(deps)\010    deps=deps or {}\010    local player=deps.player or game:GetService(\034Players\034).LocalPlayer\010    local root=deps.root or game:GetService(\034ReplicatedStorage\034):WaitForChild(\034PlatformBattles\034,15)\010    assert(root,\034Pixel Lineage is not loaded\034)\010    local shared=root.Shared\010    local config=deps.config or require(shared.GameConfig)\010    local gear=deps.gear or require(shared.GearConfig)\010    local supplies=deps.supplies or require(shared.VillageConfig)\010    local supers=deps.supers or require(shared.SuperClasses)\010    local spells=deps.spells or require(shared.ScrollSpells)\010    local energy=deps.energy or require(shared.EnergyRules)\010    local remote=deps.remote or root.Remotes:WaitForChild(\034ProfileRequest\034,15)\010    local env=deps.env or getgenv()\010    local adapter=env.AiosFeatureData\010    adapter=adapter or {Enabled=false,Pending=nil,Message=\034Choose a recipe and enable auto crafting\034,InFlight=false,Blocked=false}\010    adapter.Enabled=false\010    env.AiosFeatureData=adapter\010    local view=adapter.View\010    local counts,countProfile,countAt={},nil,-math.huge\010    local nextProfileProbeAt=-math.huge\010    function adapter:Profile()\010        if deps.profile then\010            local current=deps.profile()\010            if type(current)==\034table\034then self.CachedProfile=current;return current end\010        end\010        if not view or view.player~=player or not view.gui or not view.gui.Parent then\010            -- Owned() is called for the whole catalog. Cache misses too, so one\010            -- missing native menu cannot trigger a heap scan for every item.\010            view=nil;self.View=nil;self.LastNativeProfile=nil;self.CachedProfile=nil\010            if os.clock()<nextProfileProbeAt then return nil end\010            nextProfileProbeAt=os.clock()+2\010            local objects\010            if type(filtergc)==\034function\034then local ok,result=pcall(filtergc,\034table\034,{Keys={\034player\034,\034profile\034,\034gameConfig\034}},false);if ok then objects=result end end\010            if type(objects)~=\034table\034and type(getgc)==\034function\034then local ok,result=pcall(getgc,true);if ok then objects=result end end\010            for _,candidate in pairs(objects or {})do\010                if type(candidate)==\034table\034and rawget(candidate,\034player\034)==player then\010                    local gui=rawget(candidate,\034gui\034)\010                    if typeof(gui)==\034Instance\034and gui.Name==\034PixelGear\034and gui.Parent then view=candidate;adapter.View=view;break end\010                end\010            end\010        end\010        if view and view.profile~=self.LastNativeProfile then self.LastNativeProfile=view.profile;self.CachedProfile=view.profile end\010        return self.CachedProfile\010    end\010    function adapter:Owned(id)\010        local p=self:Profile()\010        if p~=countProfile or os.clock()-countAt>=1 then\010            counts={};countProfile=p;countAt=os.clock()\010            for key,value in pairs(p and p.inventory or {})do counts[key]=tonumber(value)or 0 end\010            for _,item in pairs(p and p.gearBag or {})do if type(item)==\034table\034and item.base then counts[item.base]=(counts[item.base]or 0)+1 end end\010        end\010        return counts[id]or 0\010    end\010    function adapter:EquippedScroll(p)\010        p=p or self:Profile();if not p then return nil end\010        for _,uid in pairs(p.gear or {})do\010            local piece=(p.gearBag or {})[uid]\010            local move=piece and (gear.ScrollMoves or {})[piece.base]\010            if move then local d=table.clone(move);d.id=\034gear_scroll\034;d.kind=\034GearScroll\034;return d end\010        end\010    end\010    function adapter:Skills()\010        local p=self:Profile();if not p then return {}end\010        local rows,seen={},{}\010        local function add(d,source)\010            if not d or not d.id or seen[d.id]or d.passive then return end\010            seen[d.id]=true;rows[#rows+1]={id=d.id,name=d.name or d.id,cost=energy.Cost(d),cooldown=d.cooldown or 0,description=d.description or \034\034,source=source,scroll=d.scrollId~=nil or d.kind==\034GearScroll\034,damage=tonumber(d.power)or 0}\010        end\010        add({id=\034basic_attack\034,name=\034Basic attack\034,description=\034Attack with your equipped weapon.\034},\034Equipped weapon\034)\010        local class=config.Classes[p.selectedClass]\010        for _,d in ipairs(class and class.skills or {})do\010            if (tonumber(p.level)or 0)>=supers.BaseSkillLevel(d)then add(d,p.selectedClass)end\010        end\010        local learned=(p.learnedSkills or {})[p.selectedClass]or {}\010        local function learnedId(id)return learned[id]==true or table.find(learned,id)~=nil end\010        local function index(t,depth)\010            if type(t)~=\034table\034or depth>5 then return end\010            if t.id and t.kind and learnedId(t.id)then add(t,p.selectedClass)end\010            for _,v in pairs(t)do if type(v)==\034table\034then index(v,depth+1)end end\010        end\010        index(class,0)\010        for i,d in ipairs(supers.Moves[p.superClass]or {})do\010            if (tonumber(p.level)or 0)>=supers.MoveLevel(i)then add(d,p.superClass)end\010        end\010        if supers.IsUltra(p)then for i,d in ipairs(supers.UltraMoves[p.superClass]or {})do if i<=supers.UltraSkillsLearned(p)then add(d,p.superClass)end end end\010        for id,known in pairs(p.learnedWorldSkills or {})do if known then add(spells.Actions[id],\034Learned scroll\034)end end\010        add(self:EquippedScroll(p),\034Equipped scroll\034)\010        table.sort(rows,function(a,b)return a.name<b.name end)\010        return rows\010    end\010    function adapter:References()\010        local p=self:Profile();if not p then return {}end\010        local http=game:GetService(\034HttpService\034)\010        local names={p.selectedClass};if p.superClass then names[#names+1]=p.superClass end\010        local ok,data=pcall(function()return http:JSONDecode(game:HttpGet(\034https://pixel-lineage.fandom.com/api.php?action=query&format=json&titles=\034..http:UrlEncode(table.concat(names,\034|\034))))end)\010        local out={}\010        if ok then for _,page in pairs(data.query and data.query.pages or {})do if page.missing==nil then out[#out+1]={name=page.title,url=\034https://pixel-lineage.fandom.com/wiki/\034..http:UrlEncode(page.title:gsub(\034 \034,\034_\034))}end end end\010        return out\010    end\010    function adapter:Recipes()\010        local rows={}\010        for _,r in ipairs(supplies.Recipes)do rows[#rows+1]={id=r.id,name=r.name,itemId=r.itemId,ingredients=table.clone(r.ingredients),amount=r.potions or 1,description=r.text}end\010        return rows\010    end\010    function adapter:Configure(enabled,recipe,target,mode)\010        if enabled and (not self.Enabled or recipe~=self.Recipe or target~=self.Target or mode~=self.Mode)then self.Run=(self.Run or 0)+1;self.Completed=0 end\010        self.Mode=mode or \034stock\034\010        if not enabled and not self.Pending then self.Blocked=false end\010        self.Enabled=enabled==true;self.Recipe=recipe;self.Target=math.clamp(math.floor(tonumber(target)or 3),1,99)\010        if not self.Enabled then self.Message=self.Pending and \034Paused; last craft awaiting confirmation\034or\034Auto crafting off\034end\010    end\010    function adapter:Plan()\010        if deps.allowCraft and not deps.allowCraft()then return nil,\034Crafting paused by access or life protection\034end\010        local p=self:Profile()\010        if not p then return nil,\034Waiting for character