.at>=12 then self.Message=\034Craft reply delayed; no duplicate request will be sent\034end\010            return\010        end\010        if self.Blocked then return end\010        local plan,why=self:Plan();self.Message=why or \034Crafting at the cauldron\034\010        if not plan then return end\010        self.Pending=plan;plan.at=os.clock();self.InFlight=true\010        task.spawn(function()\010            local ok,result=pcall(function()return remote:InvokeServer(\034Village\034,{action=\034brew\034,ingredients=plan.ingredients})end)\010            self.InFlight=false\010            local p=self:Profile()\010            if not p or p.statContext~=plan.context or p.heroSlot~=plan.hero then self.Blocked=true;self.Enabled=false;self.Message=\034Character changed; craft receipt retained\034;return end\010            if ok and type(result)==\034table\034and result.ok==false then\010                self.Pending=nil;self.Blocked=true;self.Message=tostring(result.message or \034Craft rejected; switch auto crafting off/on after fixing the cause\034)\010            elseif ok and type(result)==\034table\034and result.ok==true and type(result.profile)==\034table\034\010                and result.profile.statContext==plan.context and result.profile.heroSlot==plan.hero\010                and (tonumber((result.profile.inventory or {})[plan.itemId])or 0)>plan.before then\010                local consumed=true\010                for id,needed in pairs(plan.required)do if (tonumber((result.profile.inventory or {})[id])or 0)~=plan.materials[id]-needed then consumed=false end end\010                local after=tonumber((result.profile.inventory or {})[plan.itemId])or 0\010                if not consumed or after~=plan.before+plan.amount then self.Blocked=true;self.Message=\034Craft reply differs from recipe; receipt retained\034;return end\010                self.CachedProfile=result.profile\010                self.LastReceipt={before=plan.before,after=after,materialsBefore=pla