       end\010        return list\010    end\010    local function scalar(value)return type(value)==\034table\034and(value[1]or value.value)or value end\010    function api:SkillDecision()\010        local actions=skillRows\010        local allowed={}\010        local disabled=words(state.disabled)\010        for _,a in ipairs(actions)do\010            if not table.find(disabled,a.id) and (a.cost or 0)<=state.energy and (not a.scroll or state.useScrolls)then allowed[a.id]=a end\010        end\010        if state.skillMode==\034Automatic\034and state.finisher and state.enemyHP<=40 and allowed.basic_attack then return \034basic_attack\034,\034Sample conservative finisher\034end\010        local order=words(state.boss and state.bossPriority~=\034\034and state.bossPriority or state.priority)\010        if state.skillMode~=\034Automatic\034and #order>0 then\010            local offset=state.skillMode==\034Rotation\034and(state.turn-1)%#order or 0\010            for i=1,#order do local id=order[(i-1+offset)%#order+1];if allowed[id]then return id,\034Sample \034..state.skillMode end end\010        end\010        local best\010        for _,a in ipairs(actions)do if allowed[a.id]and(not best or (a.damage or 0)>(best.damage or 0))then best=a end end\010        return best and best.id or nil,best and \034Sample strongest available\034or\034No affordable enabled action\034\010    end\010    function api:BrewDecision()\010        if not state.useBrews then return nil,\034Brews disabled\034end\010        if state.brewUsed>=3 then return nil,\034Three-use sample run limit reached\034end\010        if state.brewStock<=0 then return nil,\034No sample stock\034end\010        if state.poisoned then return \034slime_tonic\034,\034Cleanse sample poison\034end\010        if state.energy<2 then return \034wisp_elixir\034,\034Restore sample energy\034end\010        return nil,\034No useful sample brew\034\010    end\010    function api:ConsumeBrew()\010        local id=self:BrewDecision()